import{z as n,x as d,o,c,q as l,j as r,D as E,d as a,s as B,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"稀疏文件与穿孔","description":"","frontmatter":{"title":"稀疏文件与穿孔","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sparse-files.md","filePath":"cs/sparse-files.md","lastUpdated":1791413859000}'),p={name:"cs/sparse-files.md"};function A(m,e,f,h,_,u){const t=d("Mermaid");return o(),c("div",null,[e[2]||(e[2]=l('<h1 id="稀疏文件与穿孔" tabindex="-1">稀疏文件与穿孔 <a class="header-anchor" href="#稀疏文件与穿孔" aria-label="Permalink to &quot;稀疏文件与穿孔&quot;">​</a></h1><div class="epigraph"><p>逻辑大小可以盖住从未分配的洞；读洞得零。穿孔把已分配块还回去，使中间再次变成洞。</p><footer>—— 据 POSIX lseek 与 <code>FALLOC_FL_PUNCH_HOLE</code>；McKusick 对空洞文件的讨论</footer></div><p><a href="/cs/fs-mmap-coherence">上一课</a>假定偏移对应页。若从未写入某偏移，<a href="/cs/ext4-extents">extent</a> 可以不覆盖它，FAT 链也可以跳过——但接口要统一：<strong>稀疏文件</strong>。缺口是洞的 POSIX 语义与 <code>fallocate</code> 穿孔，不是再讲块组位图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>虚拟机镜像、下载占位、科学数据经常「中间没有写过」。若按逻辑大小预分配，盘瞬间满。Unix 约定：<code>lseek</code> 越过 EOF 再写，中间是洞；<code>read</code> 洞返回零，不占块。穿孔：已有数据的区间也可以改回洞，释放块，再次读零。缺口：<code>SEEK_HOLE</code>/<code>SEEK_DATA</code> 如何让工具跳过洞；mmap 洞页是零页还是写时分配；与配额、快照的交叉（穿孔是否立刻减占用）。</p><p><span class="marginnote">数字实例：一个 100 GB 的虚拟机镜像只写了 10 GB，<code>ls</code> 显示 100 GB（逻辑大小），<code>du</code> 显示 10 GB（实际占用）。不懂 <code>SEEK_HOLE</code> 的备份工具会写出 100 GB 的真零文件，白白多用 90 GB。</span></p><p><span class="marginnote"><code>fallocate</code> 预分配与穿孔是同一系统调用的不同模式。预分配减少碎片，与稀疏相反。教学上两者都改「逻辑 vs 物理」关系。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>FS：洞不出现在块图/extent/FAT 链中。写洞中某页：分配块，插入图，页缓存从零页变成普通脏页。穿孔：切 extent 或拆链，位图清位，作废页缓存对应页。与 COW：穿孔是新树，旧快照仍握旧块。与 <a href="/cs/fsck">fsck</a>：洞不是交叉，位图空闲而逻辑大小盖住是合法。</p><p><span class="marginnote">术语翻译：穿孔（punch hole）就是「把这段已写过的内容作废、把占的块还给文件系统，之后再读全是零」。它和截断不同——逻辑大小不变，只是中间这一段变回洞。</span></p>',10)),(o(),r(i,null,{default:E(()=>[B(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20LSIZE%5B%22%E9%80%BB%E8%BE%91%E5%A4%A7%E5%B0%8F%22%5D%20--%3E%20HOLE%5B%22%E6%9C%AA%E8%A6%86%E7%9B%96%E5%81%8F%E7%A7%BB%22%5D%0A%20%20HOLE%20--%3E%20RZ%5B%22read%20%E5%BE%97%E9%9B%B6%22%5D%0A%20%20PUNCH%5B%22punch%20hole%22%5D%20--%3E%20FREE%5B%22%E8%BF%98%E5%9D%97%22%5D%0A%20%20FREE%20--%3E%20HOLE%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s("h2",{id:"机制",tabindex:"-1"},[a("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=s("p",null,[a("稀疏把「文件」从「已占用块的集合」里解放出来：对象是逻辑字节数组，物理是部分函数。备份工具若按逻辑大小拷会把洞物化成零，撑爆目标——必须懂 "),s("code",null,"SEEK_HOLE"),a("。不要把洞写成数据库 NULL：没有列，只有偏移。")],-1)),(o(),r(i,null,{default:E(()=>[B(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20CP%5B%22%E5%A4%87%E4%BB%BD%E5%B7%A5%E5%85%B7%E6%8B%B7%E8%B4%9D%E7%A8%80%E7%96%8F%E6%96%87%E4%BB%B6%22%5D%20--%3E%20Q%7B%22%E6%80%8E%E4%B9%88%E8%AF%BB%E6%B4%9E%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%8C%89%E9%80%BB%E8%BE%91%E5%A4%A7%E5%B0%8F%E7%9B%B4%E8%AF%BB%22%7C%20BAD%5B%22%E6%B4%9E%E8%A2%AB%E7%89%A9%E5%8C%96%E6%88%90%E7%9C%9F%E9%9B%B6%E5%AD%97%E8%8A%82%22%5D%0A%20%20BAD%20--%3E%20FULL%5B%22%E7%9B%AE%E6%A0%87%E7%9B%98%E8%A2%AB%E6%92%91%E7%88%86%22%5D%0A%20%20Q%20--%3E%7C%22SEEK_HOLE%20%2F%20SEEK_DATA%22%7C%20SEG%5B%22%E5%8F%AA%E6%90%AC%E6%95%B0%E6%8D%AE%E6%AE%B5%EF%BC%8C%E6%B4%9E%E6%AE%B5%E8%AE%B0%E4%B8%BA%E6%B4%9E%22%5D%0A%20%20SEG%20--%3E%20KEEP%5B%22%E7%9B%AE%E6%A0%87%E6%96%87%E4%BB%B6%E4%BF%9D%E6%8C%81%E7%A8%80%E7%96%8F%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=l('<p>这张图回答的是：同一个 100 GB 文件，备份工具的读法决定目标是 10 GB 还是 100 GB——<code>SEEK_HOLE</code> 不是优化，是「保住稀疏性」的必经接口。</p><p>mmap 共享映射写洞会分配并标脏，等于物化。私有映射写洞只物化匿名页，文件仍稀疏。</p><p><span class="marginnote">常见误区：初学者容易把「读洞得零」理解成文件系统写了零。实际上洞对应的块根本没分配：位图上它们是空闲的，零是读取路径的约定返回值，一个字节都没落盘。把它当成「有人写过零」会误判备份与同步的语义。</span></p><p>实现上：SEEK_HOLE 的精度取决于 FS：有的按 extent，有的只在整个文件级。备份若忽略它会把 TB 级洞物化成零。fallocate 预分配则相反，故意让洞消失以减运行时分配。 读法上只引用<a href="/cs/fs-mmap-coherence">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>稀疏文件与穿孔</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证网络 FS 上穿孔的每一种缓存失效。不引入压缩：压缩后「洞」与「压缩零」不同，那是具体 FS 附录。下一课把「数据块之外」的旁路字节：扩展属性与 ACL。</p><p>版本字段会变，课序钉的是机制对象「稀疏文件与穿孔」，不是某一主线内核的结构体名。 后课默认：逻辑空洞合法且可读零。名空间里的权限与键值元数据，下一课 xattr/ACL。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>洞不占块；read 零；穿孔归还已分配块。</li><li>快照可保留穿孔前的块。</li><li>扩展属性与 ACL 是下一课。</li><li>出处：POSIX；Linux fallocate；McKusick；<em>OSTEP</em>。</li></ul>',11))])}const F=n(p,[["render",A]]);export{D as __pageData,F as default};
